package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.net.*;
import java.net.http.*;
final class SignedEventsBrowserAcceptance {
 static HttpResponse<byte[]> send(BrowserTest h,String profile,String token,String secret)throws Exception {byte[] bytes=JSON.writeValueAsBytes(SignedEventsAcceptance.payload());String time=Long.toString(System.currentTimeMillis()/1000);try(var client=HttpClient.newHttpClient()){return client.send(HttpRequest.newBuilder(URI.create(h.base()+SignedEventsAcceptance.path(profile))).header("X-OpenService-API","true").header("Content-Type","application/json").header("Authorization","Bearer "+token).header("X-OpenService-Event","browser-monitoring-event").header("X-OpenService-Timestamp",time).header("X-OpenService-Signature",SignedEventsAcceptance.signature(secret,time,profile,"browser-monitoring-event",bytes)).POST(HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),HttpResponse.BodyHandlers.ofByteArray());}}
 static void run(BrowserTest h)throws Exception {
  String name="SignedBrowser"+id(),gateway,token;try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("UPDATE os_clock_policy SET active=0");db.update("UPDATE os_event_flow SET active=0");Service.createAccount(db,map("name",name,"password",WorkflowSupport.PASSWORD,"role","agent"));gateway=RecordAccess.owner(db,name);db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",gateway);token=ApiKeyWrites.issue(db,db.viewerId,gateway,map("label","Browser signed integration","table","incident","days",1)).get("token").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Signed integrations").setExact(true)).press("Enter");page.getByLabel("Record type",new Page.GetByLabelOptions().setExact(true)).selectOption("incident");ServiceOutagesBrowserAcceptance.click(page,"Choose record type");page.getByLabel("Integration name").fill("Monitoring gateway <script>");page.getByLabel("Gateway username").fill(name);page.locator("input[name=field_priority]").check();ServiceOutagesBrowserAcceptance.click(page,"Create signed integration");assertThat(page.locator("main")).containsText("Save the signing secret");String secret=page.getByLabel("Signing secret",new Page.GetByLabelOptions().setExact(true)).inputValue();assertTrue(secret.startsWith("osw_"));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Continue to integration")).press("Enter");String profile=page.url().substring(page.url().lastIndexOf('/')+1);assertThat(page.locator("main")).not().containsText(secret);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/signed-integration-light.png")).setFullPage(true));
   try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE user_id=?",gateway);db.connection.commit();}page.getByLabel("Integration availability").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save integration availability");try(var db=h.store.open()){assertEquals(0,db.count("SELECT active FROM os_signed_profile WHERE profile_id=?",profile));db.update("UPDATE os_user SET active=1 WHERE user_id=?",gateway);db.connection.commit();}page.getByLabel("Integration availability").selectOption("true");ServiceOutagesBrowserAcceptance.click(page,"Save integration availability");var accepted=send(h,profile,token,secret);assertEquals(201,accepted.statusCode(),new String(accepted.body(),java.nio.charset.StandardCharsets.UTF_8));String record=object(object(JSON.readValue(accepted.body(),java.util.Map.class).get("result")).get("record")).get("sys_id").toString();assertEquals(200,send(h,profile,token,secret).statusCode());page.reload();assertThat(page.locator("main")).containsText("browser-monitoring-event");assertThat(page.locator("main")).containsText("latest 1 of 1");ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(false,page.evaluate("Array.from(document.querySelectorAll('main .panel')).some(panel=>panel.scrollWidth>panel.clientWidth+1)"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/signed-integration-receipt-dark.png")).setFullPage(true));page.locator("article a").press("Enter");assertThat(page.locator("main")).containsText("Signed monitoring alert <script>");assertTrue(page.url().endsWith(record));page.navigate(h.base()+"/admin/integration-profiles/"+profile);ServiceOutagesBrowserAcceptance.click(page,"Rotate signing secret");String replacement=page.getByLabel("Signing secret",new Page.GetByLabelOptions().setExact(true)).inputValue();assertNotEquals(secret,replacement);assertEquals(403,send(h,profile,token,secret).statusCode());assertEquals(200,send(h,profile,token,replacement).statusCode());page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Continue to integration")).press("Enter");assertThat(page.locator("main")).not().containsText(replacement);page.getByLabel("Integration availability").selectOption("false");ServiceOutagesBrowserAcceptance.click(page,"Save integration availability");assertEquals(403,send(h,profile,token,replacement).statusCode());
  }
 }
}
